mapper.update:
UPDATE rag_document_version
SET status = 'ready', indexed_at = #{indexedAt}, row_version = row_version + 1
WHERE tenant_id = #{tenantId} AND kb_id = #{knowledgeBaseId}
  AND document_id = #{documentId} AND version_id = #{versionId}
  AND generation = #{generation} AND row_version = #{expectedRevision}
  AND status = 'processing' AND deleted = 0

UPDATE rag_document_version
SET status = #{status}, row_version = row_version + 1
WHERE tenant_id = #{tenantId} AND kb_id = #{knowledgeBaseId}
  AND document_id = #{documentId} AND version_id = #{versionId}
  AND generation = #{generation} AND row_version = #{expectedRevision}
  AND status IN ('created', 'queued', 'processing') AND deleted = 0

UPDATE rag_document_version
SET status = 'deleted', row_version = row_version + 1
WHERE tenant_id = #{tenantId} AND kb_id = #{knowledgeBaseId}
  AND document_id = #{documentId} AND version_id = #{versionId}
  AND row_version = #{expectedRevision} AND status = 'deleting' AND deleted = 0
